    }

    /// Whether the pattern matches anywhere in `subject`.
    pub fn is_match(&self, subject: &[u8]) -> bool {
        self.find_at(subject, 0).is_some()
    }

    /// `std::regex_replace(subject, re, format)` with the default flags: every
    /// non-overlapping match, left to right, is replaced by the expansion of
    /// `format`, and unmatched text is copied through.
    pub fn replace_all(&self, subject: &[u8], format: &str) -> Vec<u8> {
        let mut out = Vec::with_capacity(subject.len() + format.len());
        let mut copied = 0; // everything before this index is already emitted
        let mut search = 0;
        while search <= subject.len() {
            let Some(m) = self.find_at(subject, search) else { break };
            out.extend_from_slice(&subject[copied..m.start]);
            expand(&mut out, format, subject, &m);
            copied = m.end;
            if m.end == m.start {
                // An empty match must not be found again at the same spot, or
                // the loop would never advance.
                if m.end >= subject.len() {
                    break;
                }
                out.push(subject[m.end]);
                copied = m.end + 1;
                search = m.end + 1;
            } else {
                search = m.end;
            }
        }
        out.extend_from_slice(&subject[copied..]);
        out
    }
}

/// Expands an ECMAScript replacement string: `$$`, `$&`, ``$` ``, `$'` and
/// `$1`..`$99`.  A reference to a group that did not participate contributes
/// nothing, and a reference to a group that does not exist is copied through
/// literally, as ECMAScript prescribes.
fn expand(out: &mut Vec<u8>, format: &str, subject: &[u8], m: &Match) {
    let f = format.as_bytes();
    let mut i = 0;
    while i < f.len() {
        if f[i] != b'$' || i + 1 == f.len() {
            out.push(f[i]);
            i += 1;
            continue;
        }
        match f[i + 1] {
            b'$' => {
                out.push(b'$');
                i += 2;
            }
            b'&' => {
                out.extend_from_slice(&subject[m.start..m.end]);
                i += 2;
            }
            b'`' => {
                out.extend_from_slice(&subject[..m.start]);
                i += 2;
            }
            b'\'' => {
                out.extend_from_slice(&subject[m.end..]);
                i += 2;
            }
            b'0'..=b'9' => {
                // Two digits win over one whenever they name a real group.
                let one = (f[i + 1] - b'0') as usize;
                let two = if i + 2 < f.len() && f[i + 2].is_ascii_digit() {
                    Some(one * 10 + (f[i + 2] - b'0') as usize)
                } else {
                    None
                };
                let (group, width) = match two {
                    Some(n) if n >= 1 && n <= m.group_count() => (n, 3),
                    _ => (one, 2),
                };
                if group >= 1 && group <= m.group_count() {
                    if let Some((s, e)) = m.group(group) {
                        out.extend_from_slice(&subject[s..e]);
                    }
                    i += width;
                } else {
                    out.push(b'$');
                    i += 1;
                }
            }
            _ => {
                out.push(b'$');
                i += 1;
            }
        }
    }
}

/// Matches `node` at `at`, calling `k` with the position just past the match.
/// Returning `false` from `k` makes the node try its next alternative, which
/// is what gives the engine its backtracking.
fn match_node(
    node: &Ast,
    subject: &[u8],
    at: usize,
    slots: &mut Slots,
    k: &mut dyn FnMut(usize, &mut Slots) -> bool,
) -> bool {
    match node {
        Ast::Empty => k(at, slots),
        Ast::Byte(b) => {
            if at < subject.len() && subject[at] == *b {
                k(at + 1, slots)
            } else {
                false
            }
        }
        Ast::Any => {
            // ECMAScript's `.` excludes the line terminators.
            if at < subject.len() && subject[at] != b'\n' && subject[at] != b'\r' {
                k(at + 1, slots)
            } else {
                false
            }
        }
        Ast::Class { negated, ranges } => {
            if at >= subject.len() {
                return false;
            }
            let b = subject[at];
            let inside = ranges.iter().any(|(lo, hi)| b >= *lo && b <= *hi);
            if inside != *negated {
                k(at + 1, slots)
            } else {
                false
            }
        }
        Ast::Start => {
            if at == 0 {
                k(at, slots)
            } else {
                false
            }
        }
        Ast::End => {
            if at == subject.len() {
                k(at, slots)
            } else {
                false
            }
        }
        Ast::Seq(nodes) => match_seq(nodes, subject, at, slots, k),
        Ast::Alt(branches) => {
            for branch in branches {
                if match_node(branch, subject, at, slots, k) {
                    return true;
                }
            }
            false
        }
        Ast::Group { slot, inner } => {
            let Some(slot) = *slot else {
                return match_node(inner, subject, at, slots, k);
            };
            let (old_start, old_end) = (slots[2 * slot], slots[2 * slot + 1]);
            slots[2 * slot] = Some(at);
            let ok = match_node(inner, subject, at, slots, &mut |end, slots| {
                let saved = slots[2 * slot + 1];
                slots[2 * slot + 1] = Some(end);
                if k(end, slots) {
                    true
                } else {
                    slots[2 * slot + 1] = saved;
                    false
                }
            });
            if !ok {
                slots[2 * slot] = old_start;
                slots[2 * slot + 1] = old_end;
            }
            ok
        }
        Ast::Repeat { inner, min, max } => match_repeat(inner, *min, *max, 0, subject, at, slots, k),
    }
}

/// Concatenation: match the head, then the tail, then the caller's `k`.
fn match_seq(
    nodes: &[Ast],
    subject: &[u8],
    at: usize,
    slots: &mut Slots,
    k: &mut dyn FnMut(usize, &mut Slots) -> bool,
) -> bool {
    match nodes.split_first() {
        None => k(at, slots),
        Some((head, tail)) => match_node(head, subject, at, slots, &mut |next, slots| {
            match_seq(tail, subject, next, slots, k)
        }),
    }
}

/// Greedy repetition: prefer one more iteration, fall back to stopping here.
/// An iteration that consumed nothing is refused once the minimum is met, so
/// a nullable body cannot spin forever.
#[allow(clippy::too_many_arguments)]
fn match_repeat(
    inner: &Ast,
    min: u32,
    max: Option<u32>,
    done: u32,
    subject: &[u8],
    at: usize,
    slots: &mut Slots,
    k: &mut dyn FnMut(usize, &mut Slots) -> bool,
) -> bool {
    if max.map_or(true, |m| done < m) {
        let more = match_node(inner, subject, at, slots, &mut |next, slots| {
            if next == at && done >= min {
                return false;
            }
            match_repeat(inner, min, max, done + 1, subject, next, slots, k)
        });
        if more {
            return true;
        }
    }
    if done >= min {
        k(at, slots)
    } else {
        false
    }
}

/// Recursive-descent pattern parser.
struct Parser<'a> {
    src: &'a [u8],
    pos: usize,
    n_groups: usize,
}

impl<'a> Parser<'a> {
    fn peek(&self) -> Option<u8> {
        self.src.get(self.pos).copied()
    }

    /// `alt := seq ('|' seq)*`
    fn parse_alt(&mut self) -> Ast {
        let mut branches = vec![self.parse_seq()];
        while self.peek() == Some(b'|') {
            self.pos += 1;
            branches.push(self.parse_seq());
        }
        if branches.len() == 1 {
            branches.pop().expect("one branch")
        } else {
            Ast::Alt(branches)
        }
    }

    /// `seq := quantified*`, stopping at `|` or an unbalanced `)`.
    fn parse_seq(&mut self) -> Ast {
        let mut items = Vec::new();
        while let Some(c) = self.peek() {
            if c == b'|' || c == b')' {
                break;
            }
            items.push(self.parse_quantified());
        }
        match items.len() {
            0 => Ast::Empty,
            1 => items.pop().expect("one item"),
            _ => Ast::Seq(items),
        }
    }

    /// An atom followed by an optional `?`, `*` or `+`.
    fn parse_quantified(&mut self) -> Ast {
        let atom = self.parse_atom();
        let (min, max) = match self.peek() {
            Some(b'?') => (0, Some(1)),
            Some(b'*') => (0, None),
            Some(b'+') => (1, None),
            _ => return atom,
        };
        self.pos += 1;
        Ast::Repeat { inner: Box::new(atom), min, max }
    }

    fn parse_atom(&mut self) -> Ast {
        let c = self.peek().expect("parse_atom called at end of pattern");
        self.pos += 1;
        match c {
            b'^' => Ast::Start,
            b'$' => Ast::End,
            b'.' => Ast::Any,
            b'(' => {
                // `(?:` opens a non-capturing group; everything else captures.
                let slot = if self.src[self.pos..].starts_with(b"?:") {
                    self.pos += 2;
                    None
                } else {
                    self.n_groups += 1;
                    Some(self.n_groups)
                };
                let inner = self.parse_alt();
                assert_eq!(self.peek(), Some(b')'), "unbalanced `(` in pattern");
                self.pos += 1;
                Ast::Group { slot, inner: Box::new(inner) }
            }
            b'[' => self.parse_class(),
            b'\\' => self.parse_escape(),
            other => Ast::Byte(other),
        }
    }

    /// `[abc]`, `[^abc]`, `[a-z]`, with backslash escapes inside.
    fn parse_class(&mut self) -> Ast {
        let negated = self.peek() == Some(b'^');
        if negated {
            self.pos += 1;
        }
        let mut ranges: Vec<(u8, u8)> = Vec::new();
        let mut first = true;
        loop {
            let c = self.peek().expect("unterminated `[` in pattern");
            if c == b']' && !first {
                self.pos += 1;
                break;
            }
            first = false;
            self.pos += 1;
            let lo = if c == b'\\' { self.class_escape(&mut ranges) } else { Some(c) };
            let Some(lo) = lo else { continue };
            // A `-` that is not last starts a range.
            if self.peek() == Some(b'-')
                && self.src.get(self.pos + 1).copied().map_or(false, |n| n != b']')
            {
                self.pos += 1;
                let hi = self.peek().expect("unterminated range in pattern");
                self.pos += 1;
                let hi = if hi == b'\\' {
                    let mut scratch = Vec::new();
                    self.class_escape(&mut scratch).expect("range end must be a single byte")
                } else {
                    hi
                };
                ranges.push((lo, hi));
            } else {
                ranges.push((lo, lo));
            }
        }
        Ast::Class { negated, ranges }
    }

    /// A backslash escape inside a class.  Shorthands such as `\d` push their
    /// own ranges and return `None`; plain escapes return their byte.
    fn class_escape(&mut self, ranges: &mut Vec<(u8, u8)>) -> Option<u8> {
        let c = self.peek().expect("trailing `\\` in pattern");
        self.pos += 1;
        match c {
            b'd' => {
                ranges.push((b'0', b'9'));
                None
            }
            b'w' => {
                ranges.extend_from_slice(&WORD_RANGES);
                None
            }
            b's' => {
                ranges.extend_from_slice(&SPACE_RANGES);
                None
            }
            other => Some(literal_escape(other)),
        }
    }

    /// A backslash escape outside a class.
    fn parse_escape(&mut self) -> Ast {
        let c = self.peek().expect("trailing `\\` in pattern");
        self.pos += 1;
        match c {
            b'd' => Ast::Class { negated: false, ranges: vec![(b'0', b'9')] },
            b'D' => Ast::Class { negated: true, ranges: vec![(b'0', b'9')] },
            b'w' => Ast::Class { negated: false, ranges: WORD_RANGES.to_vec() },
            b'W' => Ast::Class { negated: true, ranges: WORD_RANGES.to_vec() },
            b's' => Ast::Class { negated: false, ranges: SPACE_RANGES.to_vec() },
            b'S' => Ast::Class { negated: true, ranges: SPACE_RANGES.to_vec() },
            other => Ast::Byte(literal_escape(other)),
        }
    }
}

const WORD_RANGES: [(u8, u8); 4] = [(b'a', b'z'), (b'A', b'Z'), (b'0', b'9'), (b'_', b'_')];
const SPACE_RANGES: [(u8, u8); 2] = [(0x09, 0x0d), (b' ', b' ')];

/// The byte an escape such as `\n` or `\.` stands for.
fn literal_escape(c: u8) -> u8 {
    match c {
        b'n' => b'\n',
        b'r' => b'\r',
        b't' => b'\t',
        b'f' => 0x0c,
        b'v' => 0x0b,
        b'0' => 0,
        other => other,
    }
}

#[cfg(test)]
mod tests {
    use super::Regex;

    fn replace(pattern: &str, subject: &str, format: &str) -> String {
        String::from_utf8(Regex::new(pattern).replace_all(subject.as_bytes(), format)).unwrap()
    }

    #[test]
    fn anchors_and_groups() {
        assert_eq!(replace("$", "cat", "s"), "cats");
        assert_eq!(replace("s$", "cats", ""), "cat");
        assert_eq!(replace("^(ox)en$", "oxen", "$1"), "ox");
        assert_eq!(replace("^(ox)en$", "boxen", "$1"), "boxen");
    }

    #[test]
    fn classes_and_alternation() {
        assert_eq!(replace("([^aeiouy]|qu)ies$", "cities", "$1y"), "city");
        assert_eq!(replace("([m|l])ice$", "mice", "$1ouse"), "mouse");
        assert_eq!(replace("([m|l])ice$", "police", "$1ouse"), "polouse");
        // Ordered alternation, and `$1` empty when the group never matched.
        assert_eq!(replace("(matr|vert|ind)ix|ex$", "index", "$1ices"), "indices");
        assert_eq!(replace("(matr|vert|ind)ix|ex$", "matrix", "$1ices"), "matrices");
    }

    #[test]
    fn optional_group_expands_to_nothing() {
        let pattern = "((a)naly|(b)a|(t)he)ses$";
        assert_eq!(replace(pattern, "bases", "$1$2sis"), "basis");
        assert_eq!(replace(pattern, "theses", "$1$2sis"), "thesis");
        // Group 2 does participate here, reproducing the original's quirk.
        assert_eq!(replace(pattern, "analyses", "$1$2sis"), "analyasis");
    }

    #[test]
    fn non_capturing_groups_and_multiple_slots() {
        assert_eq!(replace("(?:([^f])fe|([lr])f)$", "knife", "$1$2ves"), "knives");
        assert_eq!(replace("(?:([^f])fe|([lr])f)$", "wolf", "$1$2ves"), "wolves");
    }

    #[test]
    fn bytes_not_chars() {
        // A multi-byte sequence is just bytes; `.` matches one of them.
        assert_eq!(Regex::new(".").replace_all("é".as_bytes(), "x"), b"xx".to_vec());
    }

    #[test]
    fn quantifiers_are_greedy_and_terminate() {
        assert_eq!(replace("ab*c", "abbbc", "X"), "X");
        assert_eq!(replace("ab?c", "ac", "X"), "X");
        assert_eq!(replace("(a*)$", "aaa", "[$1]"), "[aaa]");
    }
}

