//! The rule tables the original library registers in `Inflector::initialize()`.
//!
//! Every pattern and replacement below is reproduced verbatim from the C++
//! build, including its quirks (`(matr|vert|ind)ix|ex$` really is anchored on
//! only one of its two branches, and `[m|l]` really does include a literal
//! `|`).  Keeping the strings intact rather than hand-coding each rule means
//! the port inherits the original's behaviour instead of an interpretation of
//! it.
//!
//! Two details decide what the tables actually do, and both were pinned down
//! against the compiled binary:
//!
//! * **Plural rules are scanned front to back and the first match wins.**  The
//!   very first rule is `$` -> `s`, which matches every possible input, so
//!   every later plural rule is unreachable: `mouse` pluralises to `mouses`,
//!   `bus` to `buss`, `quiz` to `quizs`.  The table is kept in full because it
//!   is what the library registers; the ordering is what makes it inert.
//! * **Singular rules are scanned back to front**, so the last rule
//!   registered, `(quiz)zes$`, is tried first and the catch-all `s$` -> ``
//!   is tried last.  That is why `news` singularises to `news` (via
//!   `(n)ews$`) rather than to `new`.
//!
//! The patterns carry no case-insensitivity flag, so they are matched exactly
//! as written: `CATS` is left alone while `Cats` becomes `Cat`.

/// `(pattern, replacement)` pairs applied by [`super::Inflector::pluralize`],
/// in registration order (first match wins).
pub const PLURALS: &[(&str, &str)] = &[
    ("$", "s"),
    ("s$", "s"),
    ("(ax|test)is$", "$1es"),
    ("(octop|vir)us$", "$1i"),
    ("(alias|status)$", "$1es"),
    ("(bu)s$", "$1ses"),
    ("(buffal|tomat)o$", "$1oes"),
    ("([ti])um$", "$1a"),
    ("sis$", "ses"),
    ("(?:([^f])fe|([lr])f)$", "$1$2ves"),
    ("(hive)$", "$1s"),
    ("([^aeiouy]|qu)y$", "$1ies"),
    ("(x|ch|ss|sh)$", "$1es"),
    ("(matr|vert|ind)ix|ex$", "$1ices"),
    ("([m|l])ouse$", "$1ice"),
    ("^(ox)$", "$1en"),
    ("(quiz)$", "$1zes"),
];

/// `(pattern, replacement)` pairs applied by
/// [`super::Inflector::singularize`], in registration order.  They are tried
/// in reverse, so read this list bottom-up to follow a lookup.
pub const SINGULARS: &[(&str, &str)] = &[
    ("s$", ""),
    ("(n)ews$", "$1ews"),
    ("([ti])a$", "$1um"),
    ("((a)naly|(b)a|(d)iagno|(p)arenthe|(p)rogno|(s)ynop|(t)he)ses$", "$1$2sis"),
    ("(^analy)ses$", "$1sis"),
    ("([^f])ves$", "$1fe"),
    ("(hive)s$", "$1"),
    ("(tive)s$", "$1"),
    ("([lr])ves$", "$1f"),
    ("([^aeiouy]|qu)ies$", "$1y"),
    ("(s)eries$", "$1eries"),
    ("(m)ovies$", "$1ovie"),
    ("(x|ch|ss|sh)es$", "$1"),
    ("([m|l])ice$", "$1ouse"),
    ("(bus)es$", "$1"),
    ("(o)es$", "$1"),
    ("(shoe)s$", "$1"),
    ("(cris|ax|test)es$", "$1is"),
    ("(octop|vir)i$", "$1us"),
    ("(alias|status)es$", "$1"),
    ("^(ox)en$", "$1"),
    ("(vert|ind)ices$", "$1ex"),
    ("(matr)ices$", "$1ix"),
    ("(quiz)zes$", "$1"),
];

/// Words the library refuses to inflect.  The lookup is an exact, whole-string,
/// case-sensitive comparison: `fish` is uncountable, `Fish`, `FISH` and
/// `red fish` are not.
pub const UNCOUNTABLES: &[&str] = &[
    "equipment",
    "information",
    "rice",
    "money",
    "species",
    "series",
    "fish",
    "sheep",
    "jeans",
    "police",
];

/// Acronyms registered by the original library.
pub const ACRONYMS: &[&str] = &["HTML", "HTTP", "XML", "JSON", "API"];

/// Ordinal suffixes, indexed the way [`super::Inflector::ordinal`] picks them.
pub const ORDINAL_SUFFIXES: OrdinalSuffixes = OrdinalSuffixes {
    default: "th",
    first: "st",
    second: "nd",
    third: "rd",
};

/// The four suffix literals `th`, `st`, `nd`, `rd`.
pub struct OrdinalSuffixes {
    pub default: &'static str,
    pub first: &'static str,
    pub second: &'static str,
    pub third: &'static str,
}

