//! `std::atoi`, reproduced exactly.
//!
//! The C++ program converts `argv[1]` with `std::atoi`, which glibc implements
//! as `(int) strtol(s, nullptr, 10)`.  Three consequences are visible in the
//! output and none of them match a naive `str::parse::<i32>()`:
//!
//! * junk is not an error — parsing stops at the first character that cannot
//!   continue the number, so `12abc` is 12, `abc12` is 0, `0x1A` is 0, `3.9`
//!   is 3, and an empty or all-junk string is 0;
//! * leading C-locale whitespace and a single `+`/`-` sign are accepted;
//! * the `long` result is *narrowed* to `int` rather than clamped, so
//!   `2147483648` comes out as -2147483648, `9999999999999999999` saturates to
//!   `LONG_MAX` first and then narrows to -1, and `-9999999999999999999`
//!   saturates to `LONG_MIN` and narrows to 0.

use super::ascii;

/// `(int) strtol(text, nullptr, 10)` over raw bytes.
pub fn atoi(text: &[u8]) -> i32 {
    let mut i = 0;

    while i < text.len() && ascii::is_space(text[i]) {
        i += 1;
    }

    let negative = match text.get(i) {
        Some(b'-') => {
            i += 1;
            true
        }
        Some(b'+') => {
            i += 1;
            false
        }
        _ => false,
    };

    // `strtol` accumulates in `long` and clamps to LONG_MIN/LONG_MAX on
    // overflow; the clamped value is what gets narrowed to `int`.
    let mut acc: i64 = 0;
    let mut overflowed = false;
    while let Some(&b) = text.get(i) {
        if !ascii::is_digit(b) {
            break;
        }
        if !overflowed {
            match acc.checked_mul(10).and_then(|v| v.checked_add((b - b'0') as i64)) {
                Some(v) => acc = v,
                None => overflowed = true,
            }
        }
        i += 1;
    }

    let wide = if overflowed {
        if negative {
            i64::MIN
        } else {
            i64::MAX
        }
    } else if negative {
        -acc
    } else {
        acc
    };

    // The narrowing cast gcc performs: keep the low 32 bits.
    wide as i32
}

#[cfg(test)]
mod tests {
    use super::atoi;

    fn a(s: &str) -> i32 {
        atoi(s.as_bytes())
    }

    #[test]
    fn matches_glibc() {
        assert_eq!(a(""), 0);
        assert_eq!(a("abc"), 0);
        assert_eq!(a("12abc"), 12);
        assert_eq!(a("abc12"), 0);
        assert_eq!(a(" 42"), 42);
        assert_eq!(a("\t\n 42"), 42);
        assert_eq!(a("+7"), 7);
        assert_eq!(a("--5"), 0);
        assert_eq!(a("007"), 7);
        assert_eq!(a("0x1A"), 0);
        assert_eq!(a("1e3"), 1);
        assert_eq!(a("3.9"), 3);
        assert_eq!(a("1 2"), 1);
        assert_eq!(a("-13"), -13);
    }

    #[test]
    fn narrows_instead_of_clamping() {
        assert_eq!(a("2147483647"), i32::MAX);
        assert_eq!(a("2147483648"), i32::MIN);
        assert_eq!(a("-2147483648"), i32::MIN);
        assert_eq!(a("4294967296"), 0);
        assert_eq!(a("9999999999999999999"), -1);
        assert_eq!(a("-9999999999999999999"), 0);
        assert_eq!(a("-9223372036854775808"), 0);
    }
}

