//! Pluralisation, singularisation and the plural/singular predicates.

use super::ascii;
use super::regex::Regex;
use super::rules::{PLURALS, SINGULARS, UNCOUNTABLES};
use std::sync::OnceLock;

/// A rule table entry with its pattern already compiled.
struct Rule {
    pattern: Regex,
    replacement: &'static str,
}

impl Rule {
    fn compile(table: &'static [(&'static str, &'static str)]) -> Vec<Rule> {
        table
            .iter()
            .map(|&(pattern, replacement)| Rule { pattern: Regex::new(pattern), replacement })
            .collect()
    }

    /// Applies the rule if it matches, mirroring the original's
    /// `regex_search` test followed by `regex_replace`.
    fn apply(&self, word: &[u8]) -> Option<Vec<u8>> {
        if self.pattern.is_match(word) {
            Some(self.pattern.replace_all(word, self.replacement))
        } else {
            None
        }
    }
}

/// The compiled rule tables, built once.
struct Tables {
    plurals: Vec<Rule>,
    singulars: Vec<Rule>,
}

fn tables() -> &'static Tables {
    static TABLES: OnceLock<Tables> = OnceLock::new();
    TABLES.get_or_init(|| Tables {
        plurals: Rule::compile(PLURALS),
        singulars: Rule::compile(SINGULARS),
    })
}

/// Compiles the rule tables up front, so that the first inflection does not
/// pay for it.  This is what `Inflector::initialize()` is for in the original;
/// calling it is optional here and calling it repeatedly is harmless.
pub fn initialize() {
    let _ = tables();
}

/// Whether `word` is on the uncountable list.  The comparison is exact: the
/// whole word, byte for byte, case included.  `fish` is uncountable while
/// `Fish`, `FISH`, `fishes` and `red fish` are not.
pub fn is_uncountable(word: &[u8]) -> bool {
    UNCOUNTABLES.iter().any(|&u| u.as_bytes() == word)
}

/// The plural of `word`.
///
/// In practice this appends an `s` to anything that is not uncountable,
/// because the first plural rule (`$` -> `s`) matches every input and the
/// table is scanned front to back.  So `mouse` becomes `mouses`, `bus` becomes
/// `buss` and `child` becomes `childs` — faithfully unhelpful.
pub fn pluralize(word: &[u8]) -> Vec<u8> {
    if is_uncountable(word) {
        return word.to_vec();
    }
    for rule in &tables().plurals {
        if let Some(result) = rule.apply(word) {
            return result;
        }
    }
    word.to_vec()
}

/// The singular of `word`.
///
/// The singular table is scanned back to front, so the most specific rules
/// (`(quiz)zes$`, `(matr)ices$`, ...) are tried before the catch-all `s$`
/// removal.  Patterns are case-sensitive: `Cats` singularises to `Cat` but
/// `CATS` is left alone.
pub fn singularize(word: &[u8]) -> Vec<u8> {
    if is_uncountable(word) {
        return word.to_vec();
    }
    for rule in tables().singulars.iter().rev() {
        if let Some(result) = rule.apply(word) {
            return result;
        }
    }
    word.to_vec()
}

/// Whether `word` looks plural, i.e. whether singularising it changes it.
pub fn is_plural(word: &[u8]) -> bool {
    singularize(word) != word
}

/// The complement of [`is_plural`].
pub fn is_singular(word: &[u8]) -> bool {
    !is_plural(word)
}

/// `word` with an `_id` suffix appended, as the original's `foreign_key` does;
/// `separate_class_name_and_id_with_underscore == false` drops the underscore.
pub fn foreign_key(word: &[u8], separate_with_underscore: bool) -> Vec<u8> {
    let mut out = super::format::underscore(&super::format::demodulize(word));
    out.extend_from_slice(if separate_with_underscore { b"_id" } else { b"id" });
    out
}

/// Everything after the last `::`.
pub fn demodulize(word: &[u8]) -> Vec<u8> {
    super::format::demodulize(word)
}

/// Lowercased, `_`-separated table name for a class name: the underscored
/// form, pluralised.
pub fn tableize(word: &[u8]) -> Vec<u8> {
    pluralize(&super::format::underscore(word))
}

/// Class name for a table name: the last path segment, singularised and
/// camelised.
pub fn classify(word: &[u8]) -> Vec<u8> {
    let last = match word.iter().rposition(|&b| b == b'.') {
        Some(dot) => &word[dot + 1..],
        None => word,
    };
    super::format::camelize(&singularize(last), false)
}

/// Not used by the port's entry point; kept so the module mirrors the original
/// surface.  Uppercases every ASCII byte.
pub fn upcase(word: &[u8]) -> Vec<u8> {
    ascii::upcase(word)
}

/// Lowercases every ASCII byte.
pub fn downcase(word: &[u8]) -> Vec<u8> {
    ascii::downcase(word)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn p(s: &str) -> String {
        String::from_utf8(pluralize(s.as_bytes())).unwrap()
    }

    fn s(s: &str) -> String {
