//! Ordinal numbers.

use super::rules::ORDINAL_SUFFIXES as SUFFIX;

/// The two-letter ordinal suffix for `number`.
///
/// The arithmetic is C's, on a signed `int`, with no `abs()` anywhere — which
/// is exactly why every negative number comes out as `th`: `-1 % 10` is `-1`,
/// not `1`, so it falls through to the default.  `-1` ordinalises to `-1th`
/// and `-21` to `-21th`.
///
/// Using `%` on `i32` here matches C++ truncated division, and taking
/// `number % 100` rather than `number.abs()` also keeps `i32::MIN` from
/// overflowing.
pub fn ordinal(number: i32) -> &'static str {
    if matches!(number % 100, 11 | 12 | 13) {
        return SUFFIX.default;
    }
    match number % 10 {
        1 => SUFFIX.first,
        2 => SUFFIX.second,
        3 => SUFFIX.third,
        _ => SUFFIX.default,
    }
}

/// `number` rendered in decimal with its ordinal suffix: `1st`, `2nd`, `3rd`,
/// `4th`, `11th`, `21st`, `-1th`.
pub fn ordinalize(number: i32) -> Vec<u8> {
    let mut out = number.to_string().into_bytes();
    out.extend_from_slice(ordinal(number).as_bytes());
    out
}

#[cfg(test)]
mod tests {
    use super::ordinalize;

    fn o(n: i32) -> String {
        String::from_utf8(ordinalize(n)).unwrap()
    }

    #[test]
    fn suffixes() {
        assert_eq!(o(0), "0th");
        assert_eq!(o(1), "1st");
        assert_eq!(o(2), "2nd");
        assert_eq!(o(3), "3rd");
        assert_eq!(o(4), "4th");
        assert_eq!(o(11), "11th");
        assert_eq!(o(12), "12th");
        assert_eq!(o(13), "13th");
        assert_eq!(o(21), "21st");
        assert_eq!(o(101), "101st");
        assert_eq!(o(111), "111th");
        assert_eq!(o(1011), "1011th");
    }

    #[test]
    fn negatives_always_get_th() {
        assert_eq!(o(-1), "-1th");
        assert_eq!(o(-2), "-2th");
        assert_eq!(o(-3), "-3th");
        assert_eq!(o(-11), "-11th");
        assert_eq!(o(-21), "-21th");
        assert_eq!(o(-111), "-111th");
    }

    #[test]
    fn extremes_do_not_overflow() {
        assert_eq!(o(i32::MAX), "2147483647th");
        assert_eq!(o(i32::MIN), "-2147483648th");
    }
}

