//! The string-shaping half of the library: camelising, titleising,
//! capitalising, truncating and parameterising.
//!
//! Each function was recovered by probing the compiled C++ build, and the
//! surprises are documented where they live.  The recurring theme is that the
//! original walks a `std::string` byte by byte with `<cctype>` predicates, so:
//!
//! * only the literal space `' '` counts as a word separator — a tab, newline,
//!   carriage return, vertical tab or form feed is an ordinary character;
//! * bytes outside ASCII are never case-converted and never separators, which
//!   makes `héllo` capitalise to `Héllo` and not to `HÉllo`;
//! * lengths are measured in bytes, so a truncated word can end halfway
//!   through a UTF-8 sequence.

use super::ascii;

/// Joins the `_`-separated parts of `word` into one camel-cased run.
///
/// `lowercase_first` selects the two flavours the original exposes through its
/// `bool` parameter: `false` yields `MyWord`, `true` yields `myWord`.
///
/// The rules that are easy to get wrong:
///
/// * `_` is the *only* separator; `-`, ` `, `.`, `/` and `::` are ordinary
///   characters, so `my-word` camelises to `My-word`.
/// * Characters that are not the start of a part are copied unchanged — the
///   rest of a part is never lowercased, so `hELLO` becomes `HELLO` and
///   `HTMLParser` survives as `HTMLParser`.
/// * `lowercase_first` does not lowercase anything; it only declines to
///   uppercase the very first character.  Uppercasing is then still owned by
///   whatever follows the next `_`, which is why `_id` yields `Id` for *both*
///   values of the flag, and `MyWord` stays `MyWord` even with `true`.
/// * The pending capitalisation is consumed by the next character whatever it
///   is, so a leading digit or space swallows it: `2word` stays `2word`.
/// * The acronym table (`HTML`, `HTTP`, `XML`, `JSON`, `API`) is *not*
///   consulted: `html_tag` becomes `HtmlTag`, never `HTMLTag`.
pub fn camelize(word: &[u8], lowercase_first: bool) -> Vec<u8> {
    let mut out = Vec::with_capacity(word.len());
    let mut capitalize_next = !lowercase_first;
    for &b in word {
        if b == b'_' {
            capitalize_next = true;
            continue;
        }
        if capitalize_next {
            out.push(ascii::to_upper(b));
            capitalize_next = false;
        } else {
            out.push(b);
        }
    }
    out
}

/// Capitalises the first character of every space-separated word and lowercases
/// everything else.
///
/// This is title casing in the narrowest sense: no separator is rewritten and
/// no separator other than `' '` is recognised, so `my_word` becomes
/// `My_word` (one word), `x-ray` becomes `X-ray`, and a trailing `_id` is
/// neither stripped nor capitalised.  Runs of spaces are preserved verbatim,
/// so `a  b` becomes `A  B`.
///
/// The character that opens a word is uppercased whether or not it is a
/// letter, and that consumes the pending capitalisation: `_leading` becomes
/// `_leading`, and `2word` stays `2word`.
pub fn titleize(word: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(word.len());
    let mut start_of_word = true;
    for &b in word {
        if b == b' ' {
            out.push(b);
            start_of_word = true;
        } else if start_of_word {
            out.push(ascii::to_upper(b));
            start_of_word = false;
        } else {
            out.push(ascii::to_lower(b));
        }
    }
    out
}

/// Uppercases the first byte and lowercases every other byte.
///
/// Unlike [`titleize`] this knows nothing about words: `hello WORLD` becomes
/// `Hello world`.  The first byte is uppercased even when it is not a letter,
/// in which case nothing is capitalised at all: `' lead'` stays `' lead'`.
pub fn capitalize(word: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(word.len());
    let mut bytes = word.iter().copied();
    if let Some(first) = bytes.next() {
        out.push(ascii::to_upper(first));
        out.extend(bytes.map(ascii::to_lower));
    }
    out
}

/// Shortens `word` to `length` bytes, marking the cut with `omission`.
///
/// Words that already fit are returned untouched; longer ones keep
/// `length - omission.len()` bytes and gain the omission marker, so with the
/// original's default `"..."` a 5-byte budget leaves room for two characters:
/// `person` becomes `pe...`.
///
/// Two faithful rough edges:
///
/// * the budget counts bytes, not characters, so a multi-byte sequence can be
///   cut in half and the result is then not valid UTF-8 — which is exactly why
///   this crate carries bytes rather than `String` all the way to stdout;
/// * when `omission` is longer than `length`, the C++ subtraction wraps around
///   in `size_t` and `substr` clamps the oversized count to the end of the
///   string, so the whole word is kept and the marker is appended.
pub fn truncate(word: &[u8], length: usize, omission: &[u8]) -> Vec<u8> {
    if word.len() <= length {
        return word.to_vec();
    }
    let keep = length.wrapping_sub(omission.len()).min(word.len());
    let mut out = Vec::with_capacity(keep + omission.len());
    out.extend_from_slice(&word[..keep]);
    out.extend_from_slice(omission);
    out
}

/// Turns `word` into a lowercase slug.
///
/// The classification is blunt and worth spelling out:
///
/// * ASCII letters and digits are kept, lowercased;
/// * a literal space becomes one `separator` — runs are *not* collapsed, so
///   `a b  c` becomes `a-b--c`;
/// * every other byte is dropped outright.  That covers punctuation
///   (`a.b` -> `ab`, and note that an existing `-` or `_` in the input is
///   discarded rather than kept), control characters including tab and
///   newline, and all non-ASCII bytes — so `naïve café` becomes `nave-caf`.
///
/// Leading and trailing separator runs are then stripped, which is what makes
/// `'  x  '` come out as `x` and `'---'` come out empty.
pub fn parameterize(word: &[u8], separator: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(word.len());
    for &b in word {
        if ascii::is_alnum(b) {
            out.push(ascii::to_lower(b));
        } else if b == b' ' {
            out.extend_from_slice(separator);
        }
    }

    if separator.is_empty() {
        return out;
    }

    let mut start = 0;
    while out[start..].starts_with(separator) {
        start += separator.len();
    }
    let mut end = out.len();
    while end - start >= separator.len() && out[..end].ends_with(separator) {
        end -= separator.len();
    }
    out.drain(end..);
    out.drain(..start);
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    fn s(bytes: Vec<u8>) -> String {
        String::from_utf8(bytes).unwrap()
    }

    fn cam(word: &str, lowercase_first: bool) -> String {
        s(camelize(word.as_bytes(), lowercase_first))
    }

    #[test]
    fn camelize_splits_on_underscores_only() {
        assert_eq!(cam("my_word", true), "myWord");
        assert_eq!(cam("my_word", false), "MyWord");
        assert_eq!(cam("my-word", true), "my-word");
        assert_eq!(cam("my-word", false), "My-word");
        assert_eq!(cam("my word", false), "My word");
        assert_eq!(cam("a::b", false), "A::b");
    }

    #[test]
    fn camelize_never_lowercases() {
        assert_eq!(cam("hELLO", false), "HELLO");
        assert_eq!(cam("MyWord", true), "MyWord");
        assert_eq!(cam("HTMLParser", true), "HTMLParser");
        assert_eq!(cam("ABCdef", false), "ABCdef");
        assert_eq!(cam("aB", false), "AB");
    }

    #[test]
    fn camelize_pending_capital_is_consumed_by_anything() {
        assert_eq!(cam("2word", false), "2word");
        assert_eq!(cam("1abc", false), "1abc");
        assert_eq!(cam(" lead", false), " lead");
        // A leading underscore hands the capitalisation to the next part, so
        // the flag stops mattering.
        assert_eq!(cam("_id", true), "Id");
        assert_eq!(cam("_id", false), "Id");
        assert_eq!(cam("__dbl__", true), "Dbl");
        assert_eq!(cam("trailing_", true), "trailing");
        assert_eq!(cam("ID_card", true), "IDCard");
    }

    #[test]
    fn camelize_ignores_acronyms() {
        assert_eq!(cam("html_tag", true), "htmlTag");
        assert_eq!(cam("api_key", false), "ApiKey");
        assert_eq!(cam("json_data", true), "jsonData");
        assert_eq!(cam("http_request", false), "HttpRequest");
    }

    #[test]
    fn titleize_only_breaks_on_spaces() {
        assert_eq!(s(titleize(b"my word")), "My Word");
        assert_eq!(s(titleize(b"my_word")), "My_word");
        assert_eq!(s(titleize(b"my-word")), "My-word");
        assert_eq!(s(titleize(b"x-ray")), "X-ray");
        assert_eq!(s(titleize(b"a  b")), "A  B");
        assert_eq!(s(titleize(b"a\tb")), "A\tb");
        assert_eq!(s(titleize(b"hello WORLD")), "Hello World");
        assert_eq!(s(titleize(b"HTMLParser")), "Htmlparser");
        assert_eq!(s(titleize(b"user_id")), "User_id");
        assert_eq!(s(titleize(b"_leading")), "_leading");
        assert_eq!(s(titleize(b"2word")), "2word");
        assert_eq!(s(titleize(b" lead")), " Lead");
        assert_eq!(s(titleize(b"")), "");
        assert_eq!(s(titleize("ÉCOLE".as_bytes())), "École");
        assert_eq!(s(titleize("naïve café".as_bytes())), "Naïve Café");
    }

    #[test]
    fn capitalize_lowercases_the_tail() {
        assert_eq!(s(capitalize(b"hello world")), "Hello world");
        assert_eq!(s(capitalize(b"HELLO WORLD")), "Hello world");
        assert_eq!(s(capitalize(b"hELLO")), "Hello");
        assert_eq!(s(capitalize(b" lead")), " lead");
        assert_eq!(s(capitalize(b"1abc")), "1abc");
        assert_eq!(s(capitalize(b"_abc")), "_abc");
        assert_eq!(s(capitalize(b"")), "");
        assert_eq!(s(capitalize("ÉCOLE".as_bytes())), "École");
    }

    #[test]
    fn truncate_counts_bytes() {
