        assert_eq!(s(titleize(b"my-word")), "My-word");
        assert_eq!(s(titleize(b"x-ray")), "X-ray");
        assert_eq!(s(titleize(b"a  b")), "A  B");
        assert_eq!(s(titleize(b"a\tb")), "A\tb");
        assert_eq!(s(titleize(b"hello WORLD")), "Hello World");
        assert_eq!(s(titleize(b"HTMLParser")), "Htmlparser");
        assert_eq!(s(titleize(b"user_id")), "User_id");
