        assert_eq!(s(truncate(b"abcdef", 2, b"...")), "abcdef...");
    }

    #[test]
    fn parameterize_drops_what_it_cannot_use() {
        let p = |w: &str| s(parameterize(w.as_bytes(), b"-"));
