//! A byte-faithful Rust port of the C++ `inflection` library, as far as
//! `test11` exercises it.
//!
//! The public surface mirrors the original's static-method style:
//!
//! ```
//! # use test11::inflection::Inflector;
//! Inflector::initialize();
//! assert_eq!(Inflector::pluralize("cat"), b"cats");
//! assert_eq!(Inflector::ordinalize(1), b"1st");
//! ```
//!
//! # Why everything is bytes
//!
//! The original operates on `std::string`, i.e. on bytes, using the "C" locale
//! `<cctype>` predicates.  Two consequences forced the same choice here rather
//! than the more idiomatic `String`:
//!
//! * `truncate` measures its budget in bytes and will happily cut a UTF-8
//!   sequence in half, so a faithful port has to be able to *emit* invalid
//!   UTF-8;
//! * `argv` is not guaranteed to be valid UTF-8 in the first place, and the
//!   C++ program passes whatever bytes it is given straight through.
//!
//! So the functions take `impl AsRef<[u8]>` — `&str` and `&[u8]` both work —
//! and return `Vec<u8>`, which the caller writes out verbatim.
//!
//! # Where the C++ defaults went
//!
//! `truncate` and `parameterize` have defaulted trailing parameters in C++.
//! Rust has no default arguments, so each is split in two: the short name
//! keeps the default (`"..."` and `"-"` respectively) and the `_with` variant
//! takes the value explicitly.

pub mod ascii;
pub mod cstdlib;
pub mod format;
pub mod inflect;
pub mod ordinal;
pub mod regex;
pub mod rules;

/// Namespace for the inflection operations, mirroring the original's
/// `inflection::Inflector` class of static methods.
pub struct Inflector;

impl Inflector {
    /// Compiles the rule tables.  The C++ entry point calls this first, so the
    /// port offers it too; it is idempotent, and the tables are built on first
    /// use in any case.
    pub fn initialize() {
        inflect::initialize();
    }

    /// The plural of `word` — in practice `word` with an `s` appended, unless
    /// the word is uncountable.  See [`inflect::pluralize`].
    pub fn pluralize(word: impl AsRef<[u8]>) -> Vec<u8> {
        inflect::pluralize(word.as_ref())
    }

    /// The singular of `word`.  See [`inflect::singularize`].
    pub fn singularize(word: impl AsRef<[u8]>) -> Vec<u8> {
        inflect::singularize(word.as_ref())
    }

    /// Whether singularising `word` would change it.
    pub fn is_plural(word: impl AsRef<[u8]>) -> bool {
        inflect::is_plural(word.as_ref())
    }

    /// The complement of [`Inflector::is_plural`].
    pub fn is_singular(word: impl AsRef<[u8]>) -> bool {
        inflect::is_singular(word.as_ref())
    }

    /// `number` with its ordinal suffix, e.g. `1st`.
    pub fn ordinalize(number: i32) -> Vec<u8> {
        ordinal::ordinalize(number)
    }

    /// Just the ordinal suffix for `number`, e.g. `st`.
    pub fn ordinal(number: i32) -> &'static str {
        ordinal::ordinal(number)
    }

    /// Camel-cases the `_`-separated parts of `word`; `lowercase_first`
    /// selects `myWord` over `MyWord`.  See [`format::camelize`].
    pub fn camelize(word: impl AsRef<[u8]>, lowercase_first: bool) -> Vec<u8> {
        format::camelize(word.as_ref(), lowercase_first)
    }

    /// Capitalises each space-separated word and lowercases the rest.
    /// See [`format::titleize`].
    pub fn titleize(word: impl AsRef<[u8]>) -> Vec<u8> {
        format::titleize(word.as_ref())
    }

    /// Uppercases the first byte, lowercases the others.
    pub fn capitalize(word: impl AsRef<[u8]>) -> Vec<u8> {
        format::capitalize(word.as_ref())
    }

    /// Truncates `word` to `length` bytes with the default `"..."` marker.
    pub fn truncate(word: impl AsRef<[u8]>, length: usize) -> Vec<u8> {
        format::truncate(word.as_ref(), length, b"...")
    }

    /// Truncates `word` to `length` bytes with an explicit marker.
    pub fn truncate_with(word: impl AsRef<[u8]>, length: usize, omission: impl AsRef<[u8]>) -> Vec<u8> {
        format::truncate(word.as_ref(), length, omission.as_ref())
    }

    /// Slugifies `word` with the default `-` separator.
    pub fn parameterize(word: impl AsRef<[u8]>) -> Vec<u8> {
        format::parameterize(word.as_ref(), b"-")
    }

    /// Slugifies `word` with an explicit separator.
    pub fn parameterize_with(word: impl AsRef<[u8]>, separator: impl AsRef<[u8]>) -> Vec<u8> {
        format::parameterize(word.as_ref(), separator.as_ref())
    }
}

#[cfg(test)]
mod tests {
    use super::Inflector;

    /// The five worked examples shipped in the C++ test file, end to end.
    #[test]
    fn documented_examples() {
        Inflector::initialize();
        let expected: &[(i32, &str, [&str; 11])] = &[
            (1, "cat", ["cats", "1st", "cat", "Cat", "Cat", "Cat", "cat", "cat", "cat", "cat", "0"]),
            (2, "dog", ["dogs", "2nd", "dog", "Dog", "Dog", "Dog", "dog", "dog", "dog", "dog", "0"]),
            (3, "child", ["childs", "3rd", "child", "Child", "Child", "Child", "child", "child", "child", "child", "0"]),
            (5, "person", ["persons", "5th", "person", "Person", "Person", "Person", "pe...", "person", "person", "person", "0"]),
            (10, "mouse", ["mouses", "10th", "mouse", "Mouse", "Mouse", "Mouse", "mouse", "mouse", "mouse", "mouse", "0"]),
        ];

        for (number, word, want) in expected {
            let got = [
                Inflector::pluralize(word),
                Inflector::ordinalize(*number),
                Inflector::camelize(word, true),
                Inflector::camelize(word, false),
                Inflector::titleize(word),
                Inflector::capitalize(word),
                Inflector::truncate(word, 5),
                Inflector::truncate_with(word, 10, "~"),
                Inflector::parameterize(word),
                Inflector::parameterize_with(word, "_"),
                if Inflector::is_plural(word) { b"1".to_vec() } else { b"0".to_vec() },
            ];
            for (line, (got, want)) in got.iter().zip(want).enumerate() {
                assert_eq!(got, want.as_bytes(), "word {word:?}, line {}", line + 1);
            }
        }
    }
}

