//! Rust port of `tests/test11.cpp`.
//!
//! Takes the same two positional arguments as the C++ program — a number and a
//! word — and prints the same eleven lines of inflections.  With fewer than
//! two arguments it prints nothing and exits 0, exactly like the original,
//! whose body is guarded by `if (argc > 2)`.
//!
//! Build either way:
//!
//! ```text
//! rustc -O test11.rs -o test11
//! cargo build --release
//! ```
//!
//! Output is written as raw bytes rather than through `println!`, because two
//! of the eleven lines can legitimately not be UTF-8: `argv` may carry
//! arbitrary bytes, and `truncate` cuts on a byte boundary, so a truncated
//! multi-byte character comes out half-written — as it does in C++.

#[path = "src/inflection/mod.rs"]
mod inflection;

use inflection::cstdlib::atoi;
use inflection::Inflector;
use std::io::{self, BufWriter, Write};

fn main() {
    Inflector::initialize();

    // `args_os` rather than `args`: the C++ program never validates argv, and
    // neither does this one, so a non-UTF-8 argument must not be a panic.
    let args: Vec<std::ffi::OsString> = std::env::args_os().collect();

    // `args.len()` counts the program name, so this is C's `argc > 2`.
    if args.len() > 2 {
        let number = atoi(os_bytes(&args[1]));
        let word = os_bytes(&args[2]);

        let stdout = io::stdout();
        let mut out = BufWriter::new(stdout.lock());

        // The eleven calls, in the order the C++ test makes them.
        let lines = [
            Inflector::pluralize(word),
            Inflector::ordinalize(number),
            Inflector::camelize(word, true),
            Inflector::camelize(word, false),
            Inflector::titleize(word),
            Inflector::capitalize(word),
            Inflector::truncate(word, 5),
            Inflector::truncate_with(word, 10, "~"),
            Inflector::parameterize(word),
            Inflector::parameterize_with(word, "_"),
            // `std::cout << bool` prints 1 or 0.
            bool_line(Inflector::is_plural(word)),
        ];

        for line in lines {
            out.write_all(&line).expect("write to stdout");
            out.write_all(b"\n").expect("write to stdout");
        }
    }
}

/// The raw bytes of a command-line argument, without a UTF-8 round trip.
#[cfg(unix)]
fn os_bytes(arg: &std::ffi::OsStr) -> &[u8] {
    use std::os::unix::ffi::OsStrExt;
    arg.as_bytes()
}

/// Elsewhere there is no byte view of `OsStr`, so fall back to the lossless
/// UTF-8 one; the C++ program is built for unix anyway.
#[cfg(not(unix))]
fn os_bytes(arg: &std::ffi::OsStr) -> &[u8] {
    arg.to_str().expect("argument is not valid UTF-8").as_bytes()
}

/// How `operator<<(std::ostream&, bool)` renders without `std::boolalpha`.
fn bool_line(value: bool) -> Vec<u8> {
    if value {
        b"1".to_vec()
    } else {
        b"0".to_vec()
    }
}

