    b.is_ascii_lowercase()
}

/// `std::isspace` in the C locale: space, tab, newline, vertical tab, form
/// feed and carriage return.
pub fn is_space(b: u8) -> bool {
    matches!(b, b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r')
}

