//! Byte-level character helpers.
//!
//! The C++ original stores words in `std::string` and classifies them with the
//! `<cctype>` functions under the default "C" locale, so only the 128 ASCII
//! bytes are ever letters, digits or case-convertible.  Bytes 0x80..=0xFF —
//! which is what any UTF-8 accented character or CJK glyph decomposes into —
//! are passed through untouched.
//!
//! Everything here therefore works on `u8`, never on `char`.  Using Rust's
//! `char::to_uppercase` would diverge the moment a word contains `é` (the C++
//! build leaves it alone, Rust would fold it to `É`) and would also risk
//! panicking on input that is not valid UTF-8, which `argv` may well be.

/// `std::toupper` in the C locale.
pub fn to_upper(b: u8) -> u8 {
    if b.is_ascii_lowercase() {
        b - 32
    } else {
        b
    }
}

/// `std::tolower` in the C locale.
pub fn to_lower(b: u8) -> u8 {
    if b.is_ascii_uppercase() {
        b + 32
    } else {
        b
    }
}

/// `std::isalpha` in the C locale.
pub fn is_alpha(b: u8) -> bool {
    b.is_ascii_alphabetic()
}

/// `std::isalnum` in the C locale.
pub fn is_alnum(b: u8) -> bool {
    b.is_ascii_alphanumeric()
}

/// `std::isdigit` in the C locale.
pub fn is_digit(b: u8) -> bool {
    b.is_ascii_digit()
}

/// `std::isupper` in the C locale.
pub fn is_upper(b: u8) -> bool {
    b.is_ascii_uppercase()
}

/// `std::islower` in the C locale.
pub fn is_lower(b: u8) -> bool {
    b.is_ascii_lowercase()
}

/// `std::isspace` in the C locale: space, tab, newline, vertical tab, form
/// feed and carriage return.
pub fn is_space(b: u8) -> bool {
    matches!(b, b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r')
}

/// Every byte uppercased.
pub fn upcase(bytes: &[u8]) -> Vec<u8> {
    bytes.iter().copied().map(to_upper).collect()
}

/// Every byte lowercased.
pub fn downcase(bytes: &[u8]) -> Vec<u8> {
    bytes.iter().copied().map(to_lower).collect()
}

