    use super::*;

    #[test]
    fn only_ascii_is_touched() {
        // The two bytes of `é` (0xc3 0xa9) survive upcasing intact.
        assert_eq!(upcase("héllo".as_bytes()), vec![b'H', 0xc3, 0xa9, b'L', b'L', b'O']);
        assert_eq!(downcase("HÉLLO".as_bytes()), vec![b'h', 0xc3, 0x89, b'l', b'l', b'o']);
    }

    #[test]
    fn classification_stops_at_ascii() {
        assert!(is_alpha(b'z') && !is_alpha(b'_') && !is_alpha(0xc3));
        assert!(is_alnum(b'7') && !is_alnum(b'-'));
        assert!(is_space(b'\t') && !is_space(0xa0));
    }
}

