/// `inflection::Inflector` class of static methods.
pub struct Inflector;

impl Inflector {
    /// Compiles the rule tables.  The C++ entry point calls this first, so the
    /// port offers it too; it is idempotent, and the tables are built on first
    /// use in any case.
    pub fn initialize() {
        inflect::initialize();
    }

    /// The plural of `word` — in practice `word` with an `s` appended, unless
    /// the word is uncountable.  See [`inflect::pluralize`].
    pub fn pluralize(word: impl AsRef<[u8]>) -> Vec<u8> {
        inflect::pluralize(word.as_ref())
    }

    /// The singular of `word`.  See [`inflect::singularize`].
    pub fn singularize(word: impl AsRef<[u8]>) -> Vec<u8> {
        inflect::singularize(word.as_ref())
    }

    /// Whether singularising `word` would change it.
