                Inflector::parameterize_with(word, "_"),
                if Inflector::is_plural(word) { b"1".to_vec() } else { b"0".to_vec() },
            ];
            for (line, (got, want)) in got.iter().zip(want).enumerate() {
                assert_eq!(got.as_slice(), want.as_bytes(), "word {word:?}, line {}", line + 1);
            }
        }
    }
}

