/// singular side it makes no difference (no singular rule can match an empty
/// word) but the original clearly applies it to both.
fn apply_inflections<'a>(word: &[u8], rules: impl IntoIterator<Item = &'a Rule>) -> Vec<u8> {
    if word.is_empty() || is_uncountable(word) {
        return word.to_vec();
